/// シンプルな横棒グラフ（依存0）
/// items: [{label: '一般問題', value: 0.62}, ...] の value は 0.0〜1.0
class MiniBarChart extends StatelessWidget {
  const MiniBarChart({
    super.key,
    required this.items,
    this.title,
    this.barHeight = 18,
    this.maxItems = 6,
  });

  final List<_BarItem> items;
  final String? title;
  final double barHeight;
  final int maxItems;

  @override
  Widget build(BuildContext context) {
    final visible = items.take(maxItems).toList();
    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.black12),
      ),
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (title != null) ...[
            Text(
              title!,
              style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700),
            ),
            const SizedBox(height: 8),
          ],
          ...visible.map((e) => _BarRow(item: e, barHeight: barHeight)).toList(),
        ],
      ),
    );
  }
}

class _BarRow extends StatelessWidget {
  const _BarRow({required this.item, required this.barHeight});
  final _BarItem item;
  final double barHeight;

  @override
  Widget build(BuildContext context) {
    final pct = (item.value.clamp(0.0, 1.0) * 100).toStringAsFixed(0);
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 6),
      child: Row(
        children: [
          // ラベル
          SizedBox(
            width: 120,
            child: Text(
              item.label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(color: Colors.black87),
            ),
          ),
          const SizedBox(width: 8),
          // バー
          Expanded(
            child: ClipRRect(
              borderRadius: BorderRadius.circular(8),
              child: SizedBox(
                height: barHeight,
                child: Stack(
                  fit: StackFit.expand,
                  children: [
                    Container(color: const Color(0xFFF1EAF5)), // ベース
                    FractionallySizedBox(
                      alignment: Alignment.centerLeft,
                      widthFactor: item.value.clamp(0.0, 1.0),
                      child: Container(color: const Color(0xFF5C6BC0)), // インディゴ
                    ),
                  ],
                ),
              ),
            ),
          ),
          const SizedBox(width: 8),
          // 数値
          SizedBox(
            width: 50,
            child: Text(
              '$pct%',
              textAlign: TextAlign.right,
              style: const TextStyle(
                fontFeatures: [FontFeature.tabularFigures()],
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _BarItem {
  final String label;
  final double value; // 0.0〜1.0
  _BarItem(this.label, this.value);
}

/// ========= 後方互換ヘルパー（現状の呼び出しを壊さない） =========
/// 正答率のマップ（{"一般問題": {"total":10, "correct":7}, ...}）を
/// MiniBarChart の items に変換
List<_BarItem> buildBarItemsFromStatMap(Map<String, dynamic> source) {
  final List<_BarItem> out = [];
  source.forEach((k, v) {
    if (v is Map) {
      final total = (v['total'] as num?)?.toInt() ?? 0;
      final correct = (v['correct'] as num?)?.toInt() ?? 0;
      final rate = total == 0 ? 0.0 : (correct / total);
      out.add(_BarItem(k.toString(), rate));
    }
  });
  // 正答率が高い順
  out.sort((a, b) => b.value.compareTo(a.value));
  return out;
}

/// ========= 新ロジック対応（型安全） =========

/// DomainSummary（型）→ グラフ用アイテム
List<_BarItem> buildBarItemsFromDomainSummaries(List<DomainSummary> summaries) {
  final items = summaries
      .map((s) => _BarItem(s.domain, s.accuracy))
      .toList(growable: false);
  items.sort((a, b) => b.value.compareTo(a.value)); // 高い順
  return items;
}

/// HistoryRecord のリストから直接グラフ用アイテムを構築
/// （内部で HistoryStats.domainSummaries を使用）
List<_BarItem> buildBarItemsFromHistory(List<HistoryRecord> records) {
  final summaries = HistoryStats.domainSummaries(records);
  return buildBarItemsFromDomainSummaries(summaries);
}

import 'package:flutter/material.dart';
import 'app_buttons.dart';
import 'choice_tile.dart';

class QuestionBlock extends StatelessWidget {
  final String questionText;
  final Map<String, String> choices;        // {'A':'...', 'B':'...'}
  final String questionKind;                // 'single' | 'multiple' | 'select_incorrect'

  // 単一
  final String? selectedLabel;
  final ValueChanged<String>? onSelect;

  // 複数
  final List<String>? selectedLabels;
  final ValueChanged<String>? onToggle;

  // 送信
  final VoidCallback onSubmit;

  const QuestionBlock({
    super.key,
    required this.questionText,
    required this.choices,
    required this.questionKind,
    this.selectedLabel,
    this.onSelect,
    this.selectedLabels,
    this.onToggle,
    required this.onSubmit,
  });

  bool get _isMultiple =>
      questionKind == 'multiple' || questionKind == 'select_incorrect';

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // 問題文（全画面で統一）
        Text(
          questionText,
          style: theme.textTheme.titleMedium?.copyWith(
            fontSize: 18,
            height: 1.6,
            fontWeight: FontWeight.w600,
            color: Colors.black87,
          ),
        ),
        const SizedBox(height: 12),

        // 選択肢
        ...choices.entries.map((e) {
          final label = e.key;
          final text  = e.value;

          final bool isSelected = _isMultiple
              ? (selectedLabels ?? const []).contains(label)
              : (selectedLabel == label);

          final state = isSelected
              ? ChoiceTileState.selected
              : ChoiceTileState.normal;

          return Padding(
            padding: const EdgeInsets.only(bottom: 12),
            child: ChoiceTile(
              label: label,
              text: text,
              state: state,
              onTap: _isMultiple
                  ? (onToggle == null ? null : () => onToggle!(label))
                  : (onSelect == null ? null : () => onSelect!(label)),
            ),
          );
        }),

        const SizedBox(height: 8),

        // 解答ボタン（共通ボタンに統一）
        SizedBox(
          width: double.infinity,
          child: AppButtons.primary(
            label: '解答する',
            icon: Icons.check,
            onPressed: onSubmit,
          ),
        ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'app_buttons.dart';

/// 出題コントロール一式（表示専用コンポーネント）
/// - 画面の見た目と導線は question_screen.dart と同一になるよう再現
/// - ロジック/状態は親（QuestionScreen）で保持し、ここはイベント通知のみ行う
class QuestionControls extends StatelessWidget {
  const QuestionControls({
    super.key,
    // 共通
    required this.mode, // '必修問題' / '一般問題' / '状況設定問題'
    required this.onModeChanged,
    required this.isLoading,
    required this.onGeneratePressed,

    // 一般/状況設定 共通
    required this.domainItems,
    required this.selectedDomain,
    required this.onDomainChanged,

    required this.majorItems,
    required this.selectedMajor,
    required this.onMajorChanged,

    required this.useMid,
    required this.onUseMidChanged,

    required this.midItems,
    required this.selectedMid,
    required this.onMidChanged,

    // 必修
    required this.hisshuMajorItems,
    required this.selectedHisshuMajor,
    required this.onHisshuMajorChanged,

    // 状況設定 追加
    required this.scenarioAspects, // Map<'A'..'E', 'A. ...'>
    required this.selectedScenarioAspectCode, // String? 'A'..'E'
    required this.onScenarioAspectChanged,
  });

  // ===== プロパティ =====

  // 共通
  final String mode;
  final ValueChanged<String> onModeChanged;
  final bool isLoading;
  final VoidCallback onGeneratePressed;

  // 一般/状況設定 共通
  final List<String> domainItems;
  final String selectedDomain;
  final ValueChanged<String> onDomainChanged;

  final List<String> majorItems;
  final String selectedMajor;
  final ValueChanged<String> onMajorChanged;

  final bool useMid;
  final ValueChanged<bool> onUseMidChanged;

  final List<String> midItems;
  final String? selectedMid;
  final ValueChanged<String?> onMidChanged;

  // 必修
  final List<String> hisshuMajorItems;
  final String selectedHisshuMajor;
  final ValueChanged<String> onHisshuMajorChanged;

  // 状況設定
  final Map<String, String> scenarioAspects;
  final String? selectedScenarioAspectCode;
  final ValueChanged<String?> onScenarioAspectChanged;

  static const String modeHisshu = '必修問題';
  static const String modeGeneral = '一般問題';
  static const String modeSituational = '状況設定問題';

  @override
  Widget build(BuildContext context) {
    final isGeneral = mode == modeGeneral || mode == modeSituational;
    final isSituational = mode == modeSituational;

    // ▼ ドロップダウン表示を「太字ではなく通常」に統一
    final TextStyle? ddStyle =
    Theme.of(context).textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.w400);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // 出題形式
        _LabeledBox(
          label: '出題形式',
          child: DropdownButtonHideUnderline(
            child: DropdownButton<String>(
              value: mode,
              isExpanded: true,
              style: ddStyle,
              items: const [
                DropdownMenuItem(value: modeHisshu, child: Text(modeHisshu)),
                DropdownMenuItem(value: modeGeneral, child: Text(modeGeneral)),
                DropdownMenuItem(value: modeSituational, child: Text(modeSituational)),
              ],
              onChanged: (val) {
                if (val == null) return;
                onModeChanged(val);
              },
            ),
          ),
        ),
        const SizedBox(height: 12),

        if (isGeneral) ...[
          // 分野
          _LabeledBox(
            label: '分野',
            child: DropdownButtonHideUnderline(
              child: DropdownButton<String>(
                value: domainItems.contains(selectedDomain)
                    ? selectedDomain
                    : (domainItems.isNotEmpty ? domainItems.first : null),
                isExpanded: true,
                style: ddStyle,
                items: domainItems
                    .map((e) => DropdownMenuItem(value: e, child: Text(e, style: ddStyle)))
                    .toList(),
                onChanged: (val) {
                  if (val == null) return;
                  onDomainChanged(val);
                },
              ),
            ),
          ),
          const SizedBox(height: 12),

          // 大項目
          _LabeledBox(
            label: '大項目',
            child: DropdownButtonHideUnderline(
              child: DropdownButton<String>(
                value: selectedMajor.isNotEmpty ? selectedMajor : null,
                isExpanded: true,
                style: ddStyle,
                items: majorItems
                    .map((e) => DropdownMenuItem(value: e, child: Text(e, style: ddStyle)))
                    .toList(),
                onChanged: (val) {
                  if (val == null) return;
                  onMajorChanged(val);
                },
              ),
            ),
          ),
          const SizedBox(height: 12),

          // 状況設定の観点（A〜E）
          if (isSituational) ...[
            _LabeledBox(
              label: '状況設定の観点',
              child: DropdownButtonHideUnderline(
                child: DropdownButton<String?>(
                  value: selectedScenarioAspectCode,
                  isExpanded: true,
                  style: ddStyle,
                  items: [
                    DropdownMenuItem<String?>(
                      value: null,
                      child: Text('（未選択／ランダム）', style: ddStyle),
                    ),
                    ...scenarioAspects.entries.map(
                          (e) => DropdownMenuItem<String?>(
                        value: e.key,
                        child: Text(e.value, style: ddStyle),
                      ),
                    ),
                  ],
                  onChanged: onScenarioAspectChanged,
                ),
              ),
            ),
            const SizedBox(height: 12),
          ],

          // 中項目スイッチ
          Row(
            children: [
              Switch(
                value: useMid,
                onChanged: onUseMidChanged,
              ),
              const SizedBox(width: 8),
              const Expanded(
                child: Text('中項目を指定する（オフなら裏でランダム選択）'),
              ),
            ],
          ),

          // 中項目
          if (useMid) ...[
            const SizedBox(height: 8),
            _LabeledBox(
              label: '中項目',
